pub fn write(output: &ExtractionOutput, include_unexported: bool, writer: impl Write) -> serde_json::Result<()> {
    let components: Vec<_> =
        output.components.iter().filter(|(_, entry)| include_unexported || entry.exported).collect();
    let mut distinct: FxHashMap<*const ParsedProp, &Arc<ParsedProp>> = FxHashMap::default();
    for (_, entry) in &components {
        for (_, prop) in listed_props(entry, |prop| !omits(prop)) {
            distinct.entry(Arc::as_ptr(prop)).or_insert(prop);
        }
    }
    let rendered = distinct
        .into_par_iter()
        .map(|(ptr, prop)| Ok((SendPtr(ptr), render_prop(prop)?)))
        .collect::<serde_json::Result<Vec<_>>>()?
        .into_iter()
        .map(|(ptr, raw)| (ptr.0, raw))
        .collect();
    serde_json::to_writer_pretty(writer, &Docs { components, rendered })
}

/// A prop's address, which only names the prop; nothing reads through it.
struct SendPtr(*const ParsedProp);

// SAFETY: the pointer is never dereferenced, only used as a map key.
unsafe impl Send for SendPtr {}

/// [`write`] to a string.
